/* Акцентная плашка карточки: подпись со стрелкой сверху, под ней значения.
   Подпись одна на все монеты — в макете «Текущий баланс» не повторяется. */
const heroBox=(label,vals,go)=>`<div class="hero">
  <div class="hrow"><span class="l">${label}</span><button class="cv" data-go="${go}">${I.cv}</button></div>
  ${vals}</div>`;
/* значение с курсом — одна группа: в макете между ними 4, а не общий шаг плашки */
const heroVal=(v,s='')=>`<div class="hval"><div class="v mono">${v}</div>${s?`<div class="s mono">${s}</div>`:''}</div>`;

/* Плитки воркеров. В макете все четыре одинаковые (#f3f4f6, число Primary) —
   красной подсветки проблемных состояний там нет (185:105269). */
function workerTiles(m){
  const t=(c,l,n,k)=>`<div class="tile" data-tilef="${k}"><div class="t"><i class="dot" style="background:${c}"></i><span>${l}</span><span class="spacer dim">${I.cv}</span></div><div class="n mono">${ni(n)}</div></div>`;
  return `<div class="tiles">${t('var(--pos)','Активные',m.h.a,'ok')}${t('var(--warn)','Низкий хэшрейт',m.h.l,'low')}${t('var(--neg)','Отключены',m.h.o,'off')}${t('var(--neu)','Оффлайн',m.h.f,'fail')}</div>`;
}

function incomeTable(m,n,pid){
  const R=m.c.row,u=m.c.label.split(' ')[0];
  const d=['22.07.2025 11:07','22.07.2025 11:07','11.09.2025 14:32','22.07.2025 11:07','22.07.2025 11:07','03.04.2026 09:15','27.11.2025 18:55','01.12.2025 07:53','15.06.2026 21:48','08.01.2026 02:21'];
  const hs=['510','288','320','286','256','244','200','278','298','288'];
  if(!n) return emptyBox('Дохода пока нет','Как только будет доход вы увидите здесь информацию');
  let from=0,to=n;
  if(pid){const per=perOf(pid,10),pages=Math.max(1,Math.ceil(n/per)),cur=Math.min(U.page[pid]||1,pages);from=(cur-1)*per;to=Math.min(from+per,n)}
  return `<div class="tw"><table class="tbl"><thead><tr>
    <th>Дата и время</th><th>Хэшрейт ${I.inf}</th>
    <th class="num"><span class="thico">${COIN_ICON[u]} Доход, ${u}</span></th><th class="num">Доход с 1 ${m.c.short}, ${u}</th>
    <th class="num"><span class="thico">${USD_ICON} Доход, $ ${I.inf}</span></th>
    <th class="num"><span class="thico">${I.rub} Доход, ₽ ${I.inf}</span></th>
    <th class="num">Баланс, ${u}</th><th class="num">Цена ${u}, ₽</th></tr></thead><tbody>
    ${Array.from({length:to-from},(_,j)=>{const i=from+j;return `<tr><td class="mono">${d[i%10]}</td><td class="mono">${hs[i%10]} ${m.c.unit}</td>
      <td class="num mono">${R.amount}</td><td class="num mono">${R.per}</td><td class="num mono">35,00 $</td>
      <td class="num mono">1 000,56 ₽</td><td class="num mono">${R.bal}</td><td class="num mono">${R.price} ₽</td></tr>`}).join('')}
  </tbody></table></div>${pid?pager(pid,n,10):''}`;
}

function payoutsTable(m,n){
  if(!n) return emptyBox('Выплат пока нет','Здесь появятся выплаты после первого вывода средств');
  return `<div class="tw"><table class="tbl"><thead><tr><th>Дата и время</th><th>Кошелек</th>
    <th class="num">Сумма, ${m.bal[0].s}</th><th class="num">Сумма, ₽</th><th>Статус</th></tr></thead><tbody>
    ${Array.from({length:n},(_,i)=>`<tr><td class="mono">0${(i%9)+1}.04.2026 11:0${i%9}</td>
      <td class="mono mut">bc1q…${(4000+i*37).toString(16)}</td><td class="num mono">0,0125${i%9}</td>
      <td class="num mono">74 8${i%9}0,00 ₽</td>
      <td><span class="tag ${i%7===3?'y':'g'}">${i%7===3?'В обработке':'Выплачено'}</span></td></tr>`).join('')}
  </tbody></table></div>`;
}
/* Реферальная программа (макет 185:105544): табличная карточка, внутри две
   колонки по 794 — слева медаль с дорожкой, справа панель «Общие данные». */
function refBlock(m){
  const t=m.tier, e=m.empty;
  const st=(l,v)=>`<div class="rst"><div class="l">${l}</div><div class="v">${v}</div></div>`;
  return `<div class="ch thead"><h2>Реферальная программа</h2></div>
  <div class="refrow">
    <div class="refmain">
      ${e?'<div class="hex none">0%</div>'
        :`<img class="hex" src="/tier-${t.k}.png" alt="${t.p}" width="152" height="152">`}
      <div class="refinfo">
        <div class="refstats">
          ${st('Ваша комиссия',e?'0%':`${t.p} (${t.n})`)}
          ${st('Хэшрейт рефералов',e?`0 ${m.c.unit}`:m.c.refHash)}
          <div class="refcoin">${COIN_ICON[m.bal[0].s]}
            <span><b>${m.c.refCoin[0]}</b><i>${m.c.refCoin[1]}</i></span></div>
        </div>
        ${tierTrack(m)}
      </div>
    </div>
    <div class="reftot">
      <h3>Общие данные по всем монетам</h3>
      <div class="rtgrid">
        ${st('Активные рефералы',e?0:20)}${st('Все рефералы',e?0:50)}
        ${st('Текущий баланс',e?'0 ₽':'7 500,56 ₽')}${st('Доход за все время',e?'0 ₽':'90 000,99 ₽')}
      </div>
    </div>
  </div>
  <div class="tfoot"><button class="btn link" data-go="ref">Подробно о программе</button></div>`;
}
const tierTrack=m=>`<div class="track">
  <div class="tnext"><span>До следующего уровня:</span><b class="mono">${m.empty?'0 '+m.c.unit:m.c.next}</b></div>
  <div class="tbar"><div class="tfill" style="width:${m.empty?0:TIERS[+S.tier].f}%"></div></div>
  <div class="tpts">${TIERS.map(x=>`<div class="pt"><img src="/tier-${x.k}-s.png" alt="" width="40" height="40"><span>${x.p}</span></div>`).join('')}</div></div>`;

/* --- Воркеры --- */
/* Группы площадок — лента Segment Control Line из макета «Воркеры» */
const GEO=[['Все','5 979'],['Москва','2 398'],['Псков','789'],['Ростов','15'],['Питер','16'],
  ['Пермь','16'],['Воронеж','16'],['Калининград','16'],['Нижний','16'],['Хабаровск','16'],['Казань','16']];
const WST={ok:['Активен','var(--pos)'],low:['Низкий хэшрейт','var(--warn)'],off:['Отключен','var(--neg)'],fail:['Оффлайн','var(--neu)']};
function workersList(m){
  if(m.empty) return [];
  const models=['S19 XP Hydro 2…','S21+ 235 TH/s','Q 90 TH/s','S21+ 225 TH/s'];
  const tags=['Разогнан','Готов','Без прошивки'];
  const N=S.data==='few'?3:36, r=rng(S.coin==='btc'?11:23);
  const share=[['ok',m.h.a],['low',m.h.l],['off',m.h.o],['fail',m.h.f]];
  const tot=share.reduce((s,x)=>s+x[1],0)||1, out=[];
  for(let i=0;i<N;i++){
    const p=(i+.5)/N*tot; let acc=0, st='ok';
    for(const [k,v] of share){acc+=v; if(p<=acc){st=k;break}}
    const base=225+r()*15;
    out.push({id:i+1,name:'Ant'+String(i+1).padStart(2,'0'),model:models[i%4],st,
      h5:base+5,h1:base+12,h24:base+8,rej:((i%8)+1)/100,up:99+(i%2),tag:tags[i%3],extra:i%2});
  }
  return out;
}
function workersRows(m){
  let rows=workersList(m);
  if(U.wfilter!=='all') rows=rows.filter(w=>w.st===U.wfilter);
  const q=U.q.trim().toLowerCase();
  if(q) rows=rows.filter(w=>(w.name+' '+w.model).toLowerCase().includes(q));
  const s=U.sort.workers;
  if(s) rows=[...rows].sort((a,b)=>{const x=a[s.k],y=b[s.k];
    return (typeof x==='string'?String(x).localeCompare(String(y)):x-y)*s.d});
  return rows;
}
/* Заголовок с сортировкой. tbl — своя пара ключ/направление на каждую таблицу */
const sortTh=(k,label,gs,cls='',tbl='workers')=>{const s=U.sort[tbl], on=s&&s.k===k;
  return `<th class="srt ${on?'on':''} ${gs?'gs':''} ${cls}" data-sortk="${k}" data-sorttbl="${tbl}">${label}${on?(s.d>0?I.sortUp:I.sortDn):I.sortv}</th>`};
/* Сортировка строк по вычисленному ключу */
const sortBy=(rows,tbl,val)=>{const s=U.sort[tbl]; if(!s) return rows;
  return [...rows].sort((a,b)=>{const x=val(a,s.k),y=val(b,s.k);
    return (typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'ru'))*s.d})};

V.workers=m=>{
  const st=[['Активные',m.h.a,'var(--pos)',I.ok],['Низкий хэшрейт',m.h.l,'var(--warn)',I.excl],
            ['Отключены',m.h.o,'var(--neg)',I.xc],['Оффлайн',m.h.f,'var(--neu)',I.pause]];
  const all=workersList(m), shown=workersRows(m);
  /* Счётчики в фильтре — по всему парку, как в макете (таблица показывает выборку) */
  const PC={all:m.total,ok:m.h.a,low:m.h.l,off:m.h.o,fail:m.h.f};
  const cnt=k=>PC[k];
  const per=perOf('workers',10), pages=Math.max(1,Math.ceil(shown.length/per));
  const cur=Math.min(U.page.workers||1,pages);
  const page=shown.slice((cur-1)*per,cur*per);
  const allSel=page.length&&page.every(w=>U.sel.has(w.id));
  const rows=page.map(w=>{const[lbl,col]=WST[w.st];
    return `<tr data-wk="${w.id}" class="${U.sel.has(w.id)?'sel':''}">
      <td>${cb(U.sel.has(w.id),'data-sel="'+w.id+'"')}</td><td><b>${w.name}</b></td>
      <td class="mut">${w.model}</td>
      <td><i class="dot" style="display:inline-block;background:${col};margin-right:8px"></i>${lbl}</td>
      <td class="mono">${nf(w.h5,2)} ${m.c.unit}</td><td class="mono">${nf(w.h1,2)} ${m.c.unit}</td><td class="mono">${nf(w.h24,2)} ${m.c.unit}</td>
      <td class="mono">${nf(w.rej,2)}%</td><td class="mono">${w.up}%</td><td class="mono mut">9 Апреля, 07:32</td>
      <td><span class="tag ${w.tag==='Без прошивки'?'y':''}">${w.tag}</span>${w.extra?' <span class="tag n">+1</span>':''}</td>
      <td class="dim">${I.dots}</td></tr>`}).join('');
  return `
  <div class="grid" style="grid-template-columns:1.15fr 1fr;gap:12px">
    ${card(`<div class="hero" style="min-height:104px;align-items:center"><div><div class="l">Средний хэшрейт за 24 ч</div>
      <div class="v" style="font-size:var(--fs-h3);line-height:var(--lh-h3)">${m.avg} ${m.c.unit} <span class="delta w">▲ 10%</span></div></div></div>`,'')}
    ${card(`<div class="grid g2" style="gap:14px;margin:0">
      <div><div class="cap dim">Средний хэшрейт за 5 мин</div><div class="mono" style="font-size:var(--fs-h5);line-height:var(--lh-h5);font-weight:600">${m.h5} ${m.c.unit}</div></div>
      <div><div class="cap dim">Реджект за 24 ч</div><div class="mono" style="font-size:var(--fs-h5);line-height:var(--lh-h5);font-weight:600">${m.empty?'0%':m.c.rej} <span class="delta up">▲ 10%</span></div></div>
      <div><div class="cap dim">Средний хэшрейт за 1 ч</div><div class="mono" style="font-size:var(--fs-h5);line-height:var(--lh-h5);font-weight:600">${m.h1} ${m.c.unit}</div></div>
      <div><div class="cap dim">Uptime за 24 ч</div><div class="mono" style="font-size:var(--fs-h5);line-height:var(--lh-h5);font-weight:600">${m.empty?'0%':m.c.up} <span class="delta dn">▲ 10%</span></div></div>
    </div>`)}
  </div>
  <div class="grid g4">${st.map(([l,n,c,g])=>`<div class="statcard"><div><div class="cap dim">${l}</div><div class="n mono">${ni(n)}</div></div>
    <div class="ic" style="background:${c}">${g}</div></div>`).join('')}</div>
  <!-- Лента групп — Segment Control Line из макета: текстовые вкладки со счётчиками -->
  <div class="row" style="gap:16px;margin-bottom:12px;min-width:0">
    <div class="segl" style="flex:1;min-width:0">
      ${GEO.map(([g,n])=>`<button class="${(U.geo||'Все')===g?'on':''}" data-geo="${g}">${g} <u>${n}</u></button>`).join('')}</div>
    ${S.role==='owner'?`<button class="btn link" data-modal="group" style="flex:0 0 auto">${I.pl} Создать группу</button>`:''}
  </div>
  ${card(`<div class="ch">
    <div class="seg">
      ${[['all','Все',''],['ok','Активные','var(--pos)'],['low','Низкий хэшрейт','var(--warn)'],['off','Отключены','var(--neg)'],['fail','Оффлайн','var(--neu)']]
        .map(([k,l,c])=>`<button class="${U.wfilter===k?'on':''}" data-wf="${k}">${c?`<i class="dot" style="background:${c}"></i>`:''}${l} <u>${ni(cnt(k))}</u></button>`).join('')}
    </div></div>
  <div class="ch">
    <button class="chip" data-modal="filters">${I.flt} Фильтры</button>
    <div class="spacer"></div>
    <label class="search">${I.srch}<input id="q" placeholder="Найти воркер" value="${U.q.replace(/"/g,'&quot;')}"></label>
    <button class="btn g sm" data-toast="Экспорт CSV поставлен в очередь">${I.dl} Экспорт</button></div>
  ${U.sel.size?`<div class="bulk">${cb(true)}<b>Выбрано: ${U.sel.size}</b>
    <button class="btn g sm" data-toast="Команда перезагрузки отправлена">Перезагрузить</button>
    <button class="btn g sm" data-modal="group">Привязать группу</button>
    <div class="spacer"></div><button class="btn link" data-selclear>Снять выбор</button></div>`:''}
  ${all.length?(shown.length?`<div class="tw"><table class="tbl"><thead><tr>
      <th>${cb(allSel,'data-selall')}</th>${sortTh('name','Наименование')}${sortTh('model','Модель')}${sortTh('st','Статус')}
      ${sortTh('h5','Хэшрейт, 5 мин')}${sortTh('h1','Хэшрейт, 1 ч')}${sortTh('h24','Хэшрейт, 24 ч')}${sortTh('rej','Реджект, 24 ч')}
      <th>Uptime <span class="tipi" data-tip="Доля времени за 24 часа, когда воркер присылал шары">${I.inf}</span></th><th>Отпр. шары</th><th>Мои теги</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>
      ${pager('workers',shown.length,per)}`
    :emptyBox('Ничего не найдено','Измените фильтр или поисковый запрос'))
    :emptyBox('Воркеров пока нет','Подключите первый воркер, чтобы увидеть статистику по парку')}`)}`;
};

